using System;using System.Linq;using System.Collections.Generic;using RoadRush.TerrainDraft;
namespace RoadRush.TerrainDraft.Core800 {
 internal static class DerivedBankLedger {
  sealed class Face {public string Packet;public int Index;public TerrainPoint[] V;public double Area,Grade;public readonly List<int> Neighbours=new List<int>();}
  static string Key(TerrainPoint p)=>p.X.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+p.Z.ToString("R",System.Globalization.CultureInfo.InvariantCulture);
  internal static DerivedRoadBankDescriptor[] Build(LocalTerrainMesh[] terrain,DerivedRoadBank bank,string digest){var faces=new List<Face>();var edges=new Dictionary<string,List<int>>();foreach(var p in terrain)for(int k=0;k<p.Indices.Length;k+=3){TerrainPoint At(int i)=>new TerrainPoint(p.OriginX+p.XYZ[i*3],p.OriginY+p.XYZ[i*3+1],p.OriginZ+p.XYZ[i*3+2]);var v=new[]{At(p.Indices[k]),At(p.Indices[k+1]),At(p.Indices[k+2])};if(!bank.Allows(v[0],v[1],v[2]))continue;double ux=v[1].X-v[0].X,uz=v[1].Z-v[0].Z,vx=v[2].X-v[0].X,vz=v[2].Z-v[0].Z,den=ux*vz-uz*vx,gx=((v[1].Y-v[0].Y)*vz-(v[2].Y-v[0].Y)*uz)/den,gz=(ux*(v[2].Y-v[0].Y)-vx*(v[1].Y-v[0].Y))/den;int id=faces.Count;faces.Add(new Face{Packet=p.Id,Index=k/3,V=v,Area=Math.Abs(den)/2,Grade=Math.Sqrt(gx*gx+gz*gz)});for(int e=0;e<3;e++){string a=Key(v[e]),b=Key(v[(e+1)%3]),key=string.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;if(!edges.TryGetValue(key,out var ids))edges[key]=ids=new List<int>();ids.Add(id);if(ids.Count>2)throw new ArgumentException("Bank final nonmanifold edge");}}
   foreach(var list in edges.Values)if(list.Count==2){faces[list[0]].Neighbours.Add(list[1]);faces[list[1]].Neighbours.Add(list[0]);}var seen=new HashSet<int>();var result=new List<DerivedRoadBankDescriptor>();for(int seed=0;seed<faces.Count;seed++){if(!seen.Add(seed))continue;var component=new List<int>();var queue=new Queue<int>();queue.Enqueue(seed);while(queue.Count>0){int n=queue.Dequeue();component.Add(n);foreach(int a in faces[n].Neighbours)if(seen.Add(a))queue.Enqueue(a);}if(!component.Any(i=>faces[i].Grade>1.200001))continue;if(result.Count!=0)throw new ArgumentException("Measured bank policy requires ONE connected final component; no arbitrary extra bank islands");var membership=new HashSet<int>(component);var outgoing=new Dictionary<string,(string Next,TerrainPoint Point)>();foreach(int id in component){var f=faces[id];for(int e=0;e<3;e++){var a=f.V[e];var b=f.V[(e+1)%3];string ka=Key(a),kb=Key(b),key=string.CompareOrdinal(ka,kb)<0?ka+"|"+kb:kb+"|"+ka;if(edges[key].Count(i=>membership.Contains(i))==1){if(outgoing.ContainsKey(ka))throw new ArgumentException("Bank footprint boundary branch");outgoing[ka]=(kb,a);}}}var loops=new List<double[]>();while(outgoing.Count>0){string start=outgoing.Keys.OrderBy(x=>x,StringComparer.Ordinal).First(),at=start;var loop=new List<double>();do{if(!outgoing.TryGetValue(at,out var edge))throw new ArgumentException("Bank footprint open loop");loop.Add(edge.Point.X);loop.Add(edge.Point.Z);outgoing.Remove(at);at=edge.Next;}while(at!=start);loops.Add(loop.ToArray());}double max=component.Max(i=>faces[i].Grade);if(max>2.000001)throw new ArgumentException("Derived bank exceeds2.0 envelope");result.Add(new DerivedRoadBankDescriptor("pantside-interroad-cut-bank-1",DerivedRoadBank.Recipe,bank.SourceEdgeDigest,digest,new[]{DerivedRoadBank.UpperPacket,DerivedRoadBank.LowerPacket},component.Select(i=>new DerivedBankTriangleReference(faces[i].Packet,faces[i].Index)).ToArray(),loops.ToArray(),component.Sum(i=>faces[i].Area),max));}
   return result.ToArray();
  }
 }
}
